import numpy as np
Gamma, rho = 2.0, 0.10
q = np.array([0.0, 1.0])
sigma = 0.7
# invalid input: a zero wavenumber must raise ValueError
def _catches_value_error(fn):
    try:
        fn()
    except ValueError:
        return np.array([1.0])
    return np.array([0.0])
assert np.allclose(_catches_value_error(lambda: filter_kernels(q, sigma, Gamma, rho)), target)

